const fn = new Function(code + "\nreturn { mergeSettings };");
const { mergeSettings } = fn();
const out = mergeSettings({ a: 1, b: 2 }, { b: 9 });
if (out.a !== 1 || out.b !== 9) throw new Error("mergeSettings({ a: 1, b: 2 }, { b: 9 }) should be { a: 1, b: 9 } — later sources win.");

const fn = new Function(code + "\nreturn { mergeSettings };");
const { mergeSettings } = fn();
const out = mergeSettings({ theme: "light" }, { fontSize: 14 });
if (out.theme !== "light" || out.fontSize !== 14) throw new Error("Keys that only exist in overrides should still appear in the result.");

const fn = new Function(code + "\nreturn { mergeSettings };");
const { mergeSettings } = fn();
const d = { a: 1 };
const o = { a: 2, b: 3 };
const out = mergeSettings(d, o);
if (d.a !== 1 || Object.keys(d).length !== 1) throw new Error("defaults must not be mutated — Object.assign(d, o) is the classic mistake.");
if (o.a !== 2 || o.b !== 3) throw new Error("overrides must not be mutated.");
if (out === d || out === o) throw new Error("The result must be a fresh object.");
